def make_row(entry: dict, pid: int) -> dict:
    row = {col: "" for col in COLUMNS}
    for col in COLUMNS:
        row[col] = entry.get(col, DEFAULTS.get(col, ""))
    row["Project_ID"] = f"P{pid:06d}"
    return row


def main():
    # Load existing master
    existing_rows = []
    seen_titles = set()
    with open(MASTER_FILE, "r", encoding="utf-8-sig", errors="replace") as f:
        reader = csv.DictReader(f)
        for row in reader:
            ntitle = normalize_title(row.get("Title", ""))
            seen_titles.add(ntitle)
            existing_rows.append(row)
    
    print(f"Loaded {len(existing_rows)} existing rows from master corpus")
    
    # Append new entries
    appended = 0
    for entry in NEW_ENTRIES:
        ntitle = normalize_title(entry.get("Title", ""))
        if ntitle in seen_titles:
            print(f"  SKIP (dup): {entry['Title'][:50]}")
            continue
        seen_titles.add(ntitle)
        existing_rows.append(entry)
        appended += 1
    
    print(f"Appended {appended} new entries")
    
    # Re-assign IDs
    for i, row in enumerate(existing_rows, start=1):
        row["Project_ID"] = f"P{i:06d}"
    
    # Write
    with open(MASTER_FILE, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=COLUMNS, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(existing_rows)
    
    from collections import Counter
    domain_counts = Counter(row.get("Domain", "Unknown") for row in existing_rows)
    print(f"\n{'='*60}")
    print(f"FINAL MASTER CORPUS: {len(existing_rows)} entries, {len(domain_counts)} domains")
    print(f"{'='*60}")
    for dom, cnt in sorted(domain_counts.items(), key=lambda x: -x[1]):
        print(f"  {dom:<55} {cnt:>4}")


if __name__ == "__main__":
    main()
